function envv(string $k, string $default=''): string { $cfg=$GLOBALS['BHOJJ_CONFIG']??[]; if(is_array($cfg) && isset($cfg[$k]) && is_scalar($cfg[$k])) return (string)$cfg[$k]; $v=getenv($k); return $v===false?$default:$v; }
function db(): PDO { static $pdo; if ($pdo) return $pdo; $pdo=new PDO('mysql:host='.envv('DB_HOST','localhost').';dbname='.envv('DB_NAME').';charset=utf8mb4',envv('DB_USER'),envv('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); return $pdo; }
function body(): array { $raw=file_get_contents('php://input'); $d=json_decode($raw ?: '{}',true); return is_array($d)?$d:[]; }
function out($data,int $code=200): never { http_response_code($code); echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); exit; }
function userRow(array $r): array { foreach(['emergency_contact_json','saved_addresses_json','preferences_json'] as $k){ if(isset($r[$k])) $r[str_replace('_json','',$k)]=json_decode($r[$k] ?: 'null',true); unset($r[$k]); } foreach(['is_online','is_active'] as $k) if(isset($r[$k])) $r[$k]=(bool)$r[$k]; $r['createdAt']=$r['created_at']??''; $r['restaurantId']=$r['restaurant_id']??null; $r['vehicleType']=$r['vehicle_type']??null; $r['vehicleNumber']=$r['vehicle_number']??null; $r['licenseNumber']=$r['license_number']??null; $r['alternatePhone']=$r['alternate_phone']??null; $r['dietaryPreference']=$r['dietary_preference']??null; $r['upiId']=$r['upi_id']??null; $r['shiftPreference']=$r['shift_preference']??null; foreach(['restaurant_id','vehicle_type','vehicle_number','license_number','alternate_phone','dietary_preference','upi_id','shift_preference','created_at','password_hash','updated_at','is_active','is_online'] as $k) unset($r[$k]); return $r; }

function jsonPoint($value): ?array { if(is_string($value)) $value=json_decode($value,true); if(!is_array($value)) return null; $lat=(float)($value['lat']??$value['latitude']??0); $lng=(float)($value['lng']??$value['longitude']??0); if($lat < -90 || $lat > 90 || $lng < -180 || $lng > 180 || ($lat===0.0 && $lng===0.0)) return null; return ['lat'=>$lat,'lng'=>$lng]; }
function haversineKm(float $lat1,float $lng1,float $lat2,float $lng2): float { $dLat=deg2rad($lat2-$lat1); $dLng=deg2rad($lng2-$lng1); $a=sin($dLat/2)**2+cos(deg2rad($lat1))*cos(deg2rad($lat2))*sin($dLng/2)**2; return 6371.0088*2*asin(min(1,sqrt($a))); }
function orderTransitionAllowed(string $role,string $from,string $to): bool { if($from===$to)return true; $map=[
 'restaurant'=>['placed'=>['accepted','cancelled'],'accepted'=>['preparing','cancelled'],'preparing'=>['ready_for_pickup'],'ready_for_pickup'=>['out_for_delivery']],
 'delivery'=>['out_for_delivery'=>['delivered']],
 'customer'=>['placed'=>['cancelled']],
 'admin'=>['placed'=>['accepted','cancelled'],'accepted'=>['preparing','cancelled'],'preparing'=>['ready_for_pickup','cancelled'],'ready_for_pickup'=>['out_for_delivery','cancelled'],'out_for_delivery'=>['delivered','cancelled'],'delivered'=>[],'cancelled'=>[]]
 ]; return in_array($to,$map[$role][$from]??[],true); }
function requireAuth(?string $role=null): array { if(empty($_SESSION['user_id'])) out(['success'=>false,'message'=>'Authentication required'],401); $s=db()->prepare('SELECT * FROM users WHERE id=? AND is_active=1'); $s->execute([$_SESSION['user_id']]); $u=$s->fetch(); if(!$u) out(['success'=>false,'message'=>'Session expired'],401); if($role && $u['role']!==$role) out(['success'=>false,'message'=>'Forbidden'],403); return $u; }
function approvalStatus(array $u): string { if($u['role']==='restaurant'){ if(empty($u['restaurant_id'])) return 'pending'; $s=db()->prepare('SELECT is_verified FROM restaurants WHERE id=?'); $s->execute([$u['restaurant_id']]); return ((int)$s->fetchColumn())===1?'approved':'pending'; } if($u['role']==='delivery'){ $s=db()->prepare('SELECT is_verified FROM riders WHERE user_id=?'); $s->execute([$u['id']]); return ((int)$s->fetchColumn())===1?'approved':'pending'; } return 'approved'; }
function authUser(array $u): array { $row=userRow($u); $row['approvalStatus']=approvalStatus($u); return $row; }
function requireApproved(array $u): void { if(in_array($u['role'],['restaurant','delivery'],true) && approvalStatus($u)!=='approved') out(['success'=>false,'message'=>'Account pending admin approval','approvalStatus'=>'pending'],403); }
function csrf(): string { if(empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function requireCsrf(): void { $token=$_SERVER['HTTP_X_CSRF_TOKEN']??''; if(!$token || !hash_equals($_SESSION['csrf']??'', $token)) out(['success'=>false,'message'=>'Invalid CSRF token'],419); }
