function mapMenu(array $m): array { $m['restaurantId']=$m['restaurant_id'];$m['isVeg']=(bool)$m['is_veg'];$m['reviewsCount']=(int)$m['reviews_count'];$m['inStock']=(bool)$m['in_stock'];$m['prepTimeMinutes']=(int)$m['prep_time_minutes'];$m['price']=(float)$m['price'];if($m['mrp']!==null)$m['mrp']=(float)$m['mrp'];foreach(['restaurant_id','is_veg','reviews_count','in_stock','prep_time_minutes','updated_at'] as $k)unset($m[$k]);return $m;}
